"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Activity, ArrowDownRight, ArrowRight, BadgeCheck, Building2, Check, ChevronRight, CreditCard, Database, Globe2, LayoutDashboard, LifeBuoy, MessageSquareText, PackageCheck, Pencil, Plus, Search, Shield, ShieldCheck, Sparkles, Tag, Trash2, UserPlus, Users, XCircle, CalendarClock, CircleDollarSign, FileWarning } from "lucide-react";
import { useEffect, useState, type ReactNode } from "react";
import { ActionDialog, type ActionModel } from "@/components/ui/alert-dialog";
import { DataTable, type DataColumn } from "@/components/data-table/DataTable";
import { WorkspaceSidebar } from "@/components/layout/WorkspaceSidebar";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { SelectField } from "@/components/ui/select";
import { SidebarInset, SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { ThemeToggle } from "@/components/ThemeToggle";
import { authApi, authQueryKeys } from "@/features/auth/api";
import type { AuthUser } from "@/features/auth/types";
import { PlatformSearch } from "@/features/platform/components/PlatformSearch";
import { platformApi, platformKeys, type BusinessDetails, type PlatformBusiness, type PlatformHealth, type PlatformOverview, type PlatformRole, type PlatformTicket, type SubscriptionPlan, type SupportAgent } from "@/features/platform/api";
import { ApiError, getErrorMessage } from "@/lib/api-client";
import { cn } from "@/lib/utils";

export type PlatformSection = "overview" | "businesses" | "business-detail" | "plans" | "system" | "support" | "tickets";
const superAdminNavigation = [
  { label: "Overview", href: "/admin", icon: LayoutDashboard },
  { label: "Businesses", href: "/admin/businesses", icon: Building2 },
  { label: "Plans & billing", href: "/admin/plans", icon: CreditCard },
  { label: "Support staff", href: "/admin/support", icon: LifeBuoy },
  { label: "Complaints & feedback", href: "/admin/tickets", icon: MessageSquareText },
  { label: "System health", href: "/admin/system", icon: Activity },
];
const supportNavigation = [
  { label: "Businesses", href: "/admin/businesses", icon: Building2 },
  { label: "Support desk", href: "/admin/support", icon: LifeBuoy },
  { label: "Complaints & feedback", href: "/admin/tickets", icon: MessageSquareText },
];

function initials(name: string) { return name.split(/\s+/).filter(Boolean).slice(0, 2).map((word) => word[0]).join("").toUpperCase(); }
function money(value: number | string, currency: string) { return new Intl.NumberFormat("en-NP", { style: "currency", currency, maximumFractionDigits: 0 }).format(Number(value)); }
function shortDate(value: string) { return new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(new Date(value)); }

function StatePanel({ title, description, retry, loading = false }: { title: string; description: string; retry?: () => void; loading?: boolean }) {
  return <div className="rounded-2xl border border-border bg-card p-7 sm:p-10" aria-busy={loading}><h2 className="text-lg font-semibold">{title}</h2><p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{description}</p>{retry ? <Button className="mt-5" variant="outline" onClick={retry}>Try again</Button> : null}</div>;
}

function StatTile({ label, value, detail, icon: Icon, tone = "default" }: { label: string; value: string | number; detail: string; icon: typeof Building2; tone?: "default" | "primary" }) {
  return <article className={cn("rounded-2xl border border-border/75 bg-card p-5 shadow-[0_8px_32px_-24px_rgba(14,42,31,.25)]", tone === "primary" && "bg-primary text-primary-foreground")}><div className="flex items-center justify-between gap-3"><span className={cn("text-sm font-medium", tone === "primary" ? "text-primary-foreground/75" : "text-muted-foreground")}>{label}</span><span className={cn("grid size-10 place-items-center rounded-xl", tone === "primary" ? "bg-white/10" : "bg-secondary text-primary")}><Icon aria-hidden className="size-[18px]" /></span></div><p className="mt-5 text-3xl font-semibold tracking-[-.045em]">{value}</p><p className={cn("mt-1.5 text-xs", tone === "primary" ? "text-primary-foreground/70" : "text-muted-foreground")}>{detail}</p></article>;
}

function StatusPill({ status }: { status: "ACTIVE" | "SUSPENDED" | "operational" | "degraded" }) {
  const good = status === "ACTIVE" || status === "operational";
  return <span className={cn("inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold", good ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300" : "bg-amber-500/10 text-amber-800 dark:text-amber-300")}><span className={cn("size-1.5 rounded-full", good ? "bg-emerald-500" : "bg-amber-500")} />{status === "ACTIVE" ? "Active" : status === "SUSPENDED" ? "Suspended" : status === "operational" ? "Operational" : "Needs attention"}</span>;
}

export function PlatformConsolePage({ section, businessId }: { section: PlatformSection; businessId?: string }) {
  const router = useRouter();
  const profile = useQuery({ queryKey: authQueryKeys.loggedInUser, queryFn: authApi.getLoggedInUser, retry: false, staleTime: 30_000 });
  const user = profile.data;
  const platformRole: PlatformRole | null = user?.platformRole ?? (user?.isPlatformAdmin ? "SUPER_ADMIN" : null);

  useEffect(() => {
    if (profile.error instanceof ApiError && profile.error.statusCode === 401) router.replace("/login");
  }, [profile.error, router]);
  useEffect(() => {
    if (platformRole === "SUPPORT_AGENT" && section === "overview") router.replace("/admin/support");
    if (platformRole === "SUPPORT_AGENT" && ["plans", "system"].includes(section)) router.replace("/admin/support");
  }, [platformRole, section, router]);

  if (profile.isPending) return <div className="min-h-screen animate-pulse bg-secondary/35" />;
  if (profile.isError) return <main className="grid min-h-screen place-items-center p-6"><StatePanel title="Your session needs attention" description={getErrorMessage(profile.error)} retry={() => void profile.refetch()} /></main>;
  if (!user || !platformRole) return <main className="grid min-h-screen place-items-center bg-background p-6"><section className="max-w-lg rounded-2xl border border-border bg-card p-8 text-center"><span className="mx-auto grid size-12 place-items-center rounded-2xl bg-secondary text-primary"><Shield className="size-5" /></span><h1 className="mt-4 text-xl font-semibold">Platform access required</h1><p className="mt-2 text-sm leading-6 text-muted-foreground">This area is reserved for Novara platform staff. Café roles cannot access platform administration.</p><Button className="mt-5" variant="outline" onClick={() => router.replace("/dashboard")}>Return to workspace</Button></section></main>;
  return <PlatformConsoleContent section={section} businessId={businessId} user={user} platformRole={platformRole} />;
}

function PlatformConsoleContent({ section, businessId, user, platformRole }: { section: PlatformSection; businessId?: string; user: AuthUser; platformRole: PlatformRole }) {
  const pathname = usePathname();
  const router = useRouter();
  const queryClient = useQueryClient();
  const superAdmin = platformRole === "SUPER_ADMIN";
  const [businessSearch, setBusinessSearch] = useState("");
  const [debouncedBusinessSearch, setDebouncedBusinessSearch] = useState("");
  const [action, setAction] = useState<ActionModel | null>(null);
  const [planFormOpen, setPlanFormOpen] = useState(false);
  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [planName, setPlanName] = useState("");
  const [planDescription, setPlanDescription] = useState("");
  const [planPrice, setPlanPrice] = useState("0");
  const [planCurrency, setPlanCurrency] = useState("NPR");
  const [planTrialDays, setPlanTrialDays] = useState("14");
  const [planBranches, setPlanBranches] = useState("");
  const [planStaff, setPlanStaff] = useState("");
  const [agentEmail, setAgentEmail] = useState("");
  const [notice, setNotice] = useState("");
  const [noticeError, setNoticeError] = useState(false);

  useEffect(() => { const timer = window.setTimeout(() => setDebouncedBusinessSearch(businessSearch.trim()), 250); return () => window.clearTimeout(timer); }, [businessSearch]);

  const overview = useQuery({ queryKey: platformKeys.overview, queryFn: platformApi.overview, enabled: superAdmin && section === "overview", refetchInterval: () => typeof document !== "undefined" && document.visibilityState === "visible" ? 30_000 : false, retry: false });
  const businesses = useQuery({ queryKey: platformKeys.businesses(debouncedBusinessSearch), queryFn: () => platformApi.businesses(debouncedBusinessSearch), enabled: section === "businesses", retry: false });
  const business = useQuery({ queryKey: platformKeys.business(businessId ?? ""), queryFn: () => platformApi.business(businessId!), enabled: section === "business-detail" && !!businessId, retry: false });
  const assignablePlans = useQuery({ queryKey: platformKeys.plans, queryFn: platformApi.plans, enabled: superAdmin && section === "business-detail", retry: false });
  const plans = useQuery({ queryKey: platformKeys.plans, queryFn: platformApi.plans, enabled: superAdmin && section === "plans", retry: false });
  const agents = useQuery({ queryKey: platformKeys.agents, queryFn: platformApi.agents, enabled: superAdmin && section === "support", retry: false });
  const tickets = useQuery({ queryKey: platformKeys.tickets, queryFn: platformApi.tickets, enabled: (superAdmin || platformRole === "SUPPORT_AGENT") && section === "tickets", retry: false });
  const health = useQuery({ queryKey: platformKeys.health, queryFn: platformApi.health, enabled: superAdmin && (section === "system" || section === "overview"), retry: false, refetchInterval: 60_000 });

  const actionMutation = useMutation({
    mutationFn: async (current: ActionModel) => {
      if (current.resourceIds?.length) {
        if (current.kind === "BULK_SUSPEND_BUSINESSES") return Promise.all(current.resourceIds.map((id) => platformApi.updateBusiness(id, { status: "SUSPENDED" })));
        if (current.kind === "BULK_DELETE_BUSINESSES") return Promise.all(current.resourceIds.map((id) => platformApi.deleteBusiness(id)));
      }
      if (!current.resourceId) throw new Error("The selected item is missing its identifier.");
      if (current.kind === "DELETE_BUSINESS") return platformApi.deleteBusiness(current.resourceId);
      if (current.kind === "SUSPEND_BUSINESS") return platformApi.updateBusiness(current.resourceId, { status: "SUSPENDED" });
      if (current.kind === "RESTORE_BUSINESS") return platformApi.updateBusiness(current.resourceId, { status: "ACTIVE" });
      if (current.kind === "DELETE_PLAN") return platformApi.deletePlan(current.resourceId);
      if (current.kind === "DEACTIVATE_PLAN") return platformApi.updatePlan(current.resourceId, { isActive: false });
      if (current.kind === "ACTIVATE_PLAN") return platformApi.updatePlan(current.resourceId, { isActive: true });
      if (current.kind === "REMOVE_SUPPORT_AGENT") return platformApi.removeAgent(current.resourceId);
    },
    onSuccess: async (_, current) => {
      setAction(null); setNotice(`${current.subject} updated successfully.`); setNoticeError(false);
      await queryClient.invalidateQueries({ queryKey: platformKeys.all });
    },
    onError: (error) => { setNotice(getErrorMessage(error)); setNoticeError(true); },
  });
  const savePlanMutation = useMutation({
    mutationFn: ({ id, input }: { id: string | null; input: { name: string; description: string | null; priceMonthly: number; currency: string; trialDays: number; maxBranches: number | null; maxStaff: number | null } }) => id ? platformApi.updatePlan(id, input) : platformApi.createPlan(input),
    onSuccess: async (_, { id }) => { setPlanFormOpen(false); setEditingPlanId(null); setPlanName(""); setPlanDescription(""); setPlanPrice("0"); setNotice(id ? "Subscription plan updated." : "Subscription plan created."); setNoticeError(false); await queryClient.invalidateQueries({ queryKey: platformKeys.all }); },
    onError: (error) => { setNotice(getErrorMessage(error)); setNoticeError(true); },
  });
  const addAgentMutation = useMutation({
    mutationFn: platformApi.addAgent,
    onSuccess: async (agent) => { setAgentEmail(""); setNotice(`${agent.user.name} now has Support Agent access.`); setNoticeError(false); await queryClient.invalidateQueries({ queryKey: platformKeys.all }); },
    onError: (error) => { setNotice(getErrorMessage(error)); setNoticeError(true); },
  });
  const ticketMutation = useMutation({ mutationFn: ({ id, status }: { id: string; status: PlatformTicket["status"] }) => platformApi.updateTicket(id, status), onSuccess: async () => { setNotice("Ticket status updated."); setNoticeError(false); await queryClient.invalidateQueries({ queryKey: platformKeys.tickets }); }, onError: (error) => { setNotice(getErrorMessage(error)); setNoticeError(true); } });
  const assignPlanMutation = useMutation({
    mutationFn: (planId: string | null) => platformApi.updateBusiness(businessId!, { planId }),
    onSuccess: async () => { setNotice("Business plan updated."); setNoticeError(false); await queryClient.invalidateQueries({ queryKey: platformKeys.all }); },
    onError: (error) => { setNotice(getErrorMessage(error)); setNoticeError(true); },
  });

  const title = section === "overview" ? "Platform overview" : section === "businesses" ? "Businesses" : section === "business-detail" ? "Business details" : section === "plans" ? "Plans & billing" : section === "system" ? "System health" : section === "tickets" ? "Complaints & feedback" : platformRole === "SUPER_ADMIN" ? "Support staff" : "Support workspace";
  const description = section === "overview" ? "A live view of businesses, accounts and the Novara platform." : section === "businesses" ? "Search, inspect and manage every business on Novara." : section === "business-detail" ? "Review business status, branches, plan and team access." : section === "plans" ? "Set the plans available to businesses and control plan availability." : section === "system" ? "Service health and runtime status for the platform." : section === "tickets" ? "Triage customer complaints, feedback and support requests." : platformRole === "SUPER_ADMIN" ? "Manage the people who help Novara customers." : "Search business workspaces and review account context for customer support.";
  const navItems = superAdmin ? superAdminNavigation : supportNavigation;
  const allowedSection = superAdmin || ["businesses", "business-detail", "support", "tickets"].includes(section);

  function showNotice(message: string, error = false) { setNotice(message); setNoticeError(error); }
  function openAction(model: ActionModel) { setNotice(""); setAction(model); }

  const platformSidebarFooter = <div className="rounded-xl border border-sidebar-border/70 bg-sidebar-accent/60 p-3"><div className="flex items-center gap-2"><span className="size-1.5 rounded-full bg-emerald-500" /><span className="text-xs font-semibold">Platform access active</span></div><p className="mt-1.5 text-[11px] leading-5 text-muted-foreground">{superAdmin ? "Protected administrative workspace" : "Support role · limited permissions"}</p></div>;
  const platformSidebarTop = <div className="mx-4 mb-3 rounded-xl border border-sidebar-border/70 bg-background/70 p-3"><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground"><Globe2 className="size-4" /></span><div className="min-w-0"><p className="truncate text-sm font-semibold">Novara Platform</p><p className="mt-0.5 text-xs text-muted-foreground">{superAdmin ? "Control center" : "Customer support"}</p></div></div></div>;

  let page: React.ReactNode;
  if (!allowedSection) page = <StatePanel title="This platform page is restricted" description="Your Support Agent role can search business workspaces but cannot change billing, system settings, or platform staff." />;
  else if (section === "overview") page = <OverviewSection query={overview} health={health.data} onNavigate={(path) => router.push(path)} />;
  else if (section === "businesses") page = <BusinessesSection query={businesses} value={businessSearch} onChange={setBusinessSearch} onAction={openAction} canManage={superAdmin} />;
  else if (section === "business-detail") page = <BusinessDetailSection query={business} plans={assignablePlans.data ?? []} canManage={superAdmin} planPending={assignPlanMutation.isPending || assignablePlans.isPending} onPlanChange={(planId) => assignPlanMutation.mutate(planId)} onAction={openAction} onBack={() => router.push("/admin/businesses")} />;
  else if (section === "plans") page = <PlansSection query={plans} formOpen={planFormOpen} setFormOpen={(open) => { setPlanFormOpen(open); if (!open) setEditingPlanId(null); }} editing={!!editingPlanId} name={planName} setName={setPlanName} description={planDescription} setDescription={setPlanDescription} price={planPrice} setPrice={setPlanPrice} currency={planCurrency} setCurrency={setPlanCurrency} trialDays={planTrialDays} setTrialDays={setPlanTrialDays} branches={planBranches} setBranches={setPlanBranches} staff={planStaff} setStaff={setPlanStaff} pending={savePlanMutation.isPending} onEdit={(plan) => { setEditingPlanId(plan.id); setPlanName(plan.name); setPlanDescription(plan.description ?? ""); setPlanPrice(String(plan.priceMonthly)); setPlanCurrency(plan.currency); setPlanTrialDays(String(plan.trialDays)); setPlanBranches(plan.maxBranches ? String(plan.maxBranches) : ""); setPlanStaff(plan.maxStaff ? String(plan.maxStaff) : ""); setPlanFormOpen(true); }} onSave={() => {
    if (!planName.trim()) { showNotice("Enter a name for the plan.", true); return; }
    savePlanMutation.mutate({ id: editingPlanId, input: { name: planName.trim(), description: planDescription.trim() || null, priceMonthly: Number(planPrice), currency: planCurrency.toUpperCase(), trialDays: Number(planTrialDays), maxBranches: planBranches ? Number(planBranches) : null, maxStaff: planStaff ? Number(planStaff) : null } });
  }} onAction={openAction} />;
  else if (section === "system") page = <SystemSection query={health} />;
  else if (section === "tickets") page = <PlatformTicketsSection query={tickets} pending={ticketMutation.isPending} canResolveBusinessComplaints={superAdmin} onStatusChange={(id, status) => ticketMutation.mutate({ id, status })} />;
  else page = superAdmin ? <SupportStaffSection query={agents} email={agentEmail} onEmail={setAgentEmail} pending={addAgentMutation.isPending} onAdd={() => { if (!agentEmail.trim()) { showNotice("Enter the account email to assign.", true); return; } addAgentMutation.mutate(agentEmail.trim()); }} onAction={openAction} /> : <SupportWorkspaceSection />;

  const actionPending = actionMutation.isPending;
  return <SidebarProvider>
    <WorkspaceSidebar role={platformRole} tenantName="Novara Platform" groups={[{ label: "Platform", items: navItems }]} activePath={pathname} brandHref={superAdmin ? "/admin" : "/admin/support"} topContent={platformSidebarTop} footer={platformSidebarFooter} />
    <SidebarInset>
      <header className="sticky top-0 z-30 flex h-[72px] items-center justify-between gap-3 border-b border-border/60 bg-background/85 px-4 backdrop-blur-xl sm:px-7 xl:px-9"><div className="flex min-w-0 items-center gap-2"><SidebarTrigger /><div className="min-w-0"><p className="hidden text-[10px] font-semibold uppercase tracking-[.16em] text-muted-foreground sm:block">Novara · Platform</p><h1 className="truncate text-base font-semibold tracking-tight sm:text-lg">{title}</h1></div></div><div className="flex items-center gap-2"><PlatformSearch platformRole={platformRole} /><Button variant="ghost" size="icon-lg" aria-label="Search the platform" className="md:hidden" onClick={() => window.dispatchEvent(new KeyboardEvent("keydown", { key: "k", metaKey: true }))}><Search className="size-4" /></Button><ThemeToggle /><div className="mx-1 hidden h-8 w-px bg-border sm:block" /><div className="hidden items-center gap-2 sm:flex"><span className="grid size-9 place-items-center rounded-full bg-primary text-xs font-semibold text-primary-foreground">{initials(user.name)}</span><div className="hidden xl:block"><p className="text-xs font-semibold">{user.name}</p><p className="mt-0.5 text-[10px] text-muted-foreground">{platformRole === "SUPER_ADMIN" ? "Super Admin" : "Support Agent"}</p></div></div></div></header>
      <div className="mx-auto w-full max-w-[1480px] p-4 pb-10 sm:p-7 xl:px-10 xl:py-8"><div className="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p className="text-sm text-muted-foreground">{new Intl.DateTimeFormat("en", { weekday: "long", month: "long", day: "numeric", timeZone: "Asia/Kathmandu" }).format(new Date())}</p><h2 className="mt-1 text-2xl font-semibold tracking-[-.03em] sm:text-[28px]">{title}</h2><p className="mt-1.5 text-sm text-muted-foreground">{description}</p></div></div>
        {notice ? <div role={noticeError ? "alert" : "status"} className={cn("mb-5 flex items-start justify-between gap-3 rounded-xl border px-4 py-3 text-sm", noticeError ? "border-destructive/30 bg-destructive/5 text-destructive" : "border-emerald-600/20 bg-emerald-500/5 text-foreground")}><span>{notice}</span><button aria-label="Dismiss notice" onClick={() => setNotice("")}><XCircle className="size-4" /></button></div> : null}
        {page}
        <footer className="mt-9 flex flex-wrap items-center justify-between gap-3 border-t border-border/60 pt-5 text-xs text-muted-foreground"><span>Novara platform operations</span><span className="inline-flex items-center gap-1.5"><ShieldCheck className="size-3.5" />{platformRole === "SUPER_ADMIN" ? "Super Admin controls" : "Support Agent access"}</span></footer>
      </div>
    </SidebarInset>
    {action ? <ActionDialog action={action} open pending={actionPending} onOpenChange={(open) => { if (!open) setAction(null); }} onConfirm={() => actionMutation.mutate(action)} error={actionMutation.error ? getErrorMessage(actionMutation.error) : undefined} /> : null}
  </SidebarProvider>;
}

function OverviewSection({ query, health, onNavigate }: { query: { data?: PlatformOverview; isPending: boolean; isError: boolean; error: unknown; refetch: () => unknown }; health?: PlatformHealth; onNavigate: (path: string) => void }) {
  if (query.isPending) return <LoadingGrid />;
  if (query.isError || !query.data) return <StatePanel title="Platform overview is unavailable" description={getErrorMessage(query.error)} retry={() => void query.refetch()} />;
  const { metrics, recentBusinesses } = query.data;
  const mrrText = metrics.monthlyRecurringRevenue.length ? metrics.monthlyRecurringRevenue.map((item) => money(item.amount, item.currency)).join(" · ") : "No active subscriptions";
  return <>
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatTile label="Total businesses" value={metrics.businesses} detail="Registered workspaces" icon={Building2} tone="primary" /><StatTile label="Active businesses" value={metrics.activeBusinesses} detail={`${metrics.suspendedBusinesses} suspended`} icon={BadgeCheck} /><StatTile label="Monthly recurring revenue" value={mrrText} detail="Active subscriptions · grouped by currency" icon={CircleDollarSign} /><StatTile label="Trials ending soon" value={metrics.trialsEndingSoon} detail="Trial ends within 7 days" icon={CalendarClock} /></section>
    <section className="mt-4 grid gap-4 sm:grid-cols-2"><StatTile label="Past-due subscriptions" value={metrics.pastDueSubscriptions} detail="Billing follow-up required" icon={FileWarning} /><StatTile label="System health" value={health?.status === "operational" ? "Operational" : health?.status === "degraded" ? "Degraded" : "Checking"} detail={health ? `${health.services.filter((service) => service.status === "operational").length}/${health.services.length} core services operational` : "Health check is loading"} icon={Activity} /></section>
    <section className="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1.5fr)_minmax(280px,.8fr)]"><article className="overflow-hidden rounded-2xl border border-border/75 bg-card"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4 sm:px-6"><div><p className="text-xs font-medium text-muted-foreground">Recent activity</p><h3 className="mt-1 text-lg font-semibold">New businesses</h3></div><Button variant="outline" onClick={() => onNavigate("/admin/businesses")}>View all <ArrowRight className="size-4" /></Button></div>{recentBusinesses.length ? <div className="divide-y divide-border">{recentBusinesses.slice(0, 6).map((business) => <BusinessListRow key={business.id} business={business} onClick={() => onNavigate(`/admin/businesses/${business.id}`)} />)}</div> : <EmptyState icon={Building2} title="No businesses yet" description="New workspaces will appear here after they register." />}</article>
      <aside className="rounded-2xl border border-border/75 bg-card p-5 sm:p-6"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-secondary text-primary"><Sparkles className="size-5" /></span><div><p className="text-xs text-muted-foreground">Operations</p><h3 className="text-lg font-semibold">Platform snapshot</h3></div></div><div className="mt-6 space-y-4"><HealthSummaryRow label="Active businesses" value={`${metrics.activeBusinesses}`} /><HealthSummaryRow label="Suspended businesses" value={`${metrics.suspendedBusinesses}`} /><HealthSummaryRow label="Plans without assignment" value={`${metrics.activePlans} plans · ${metrics.unassignedBusinesses} businesses`} /></div><button data-control-layout="content" className="mt-6 flex w-full items-center justify-between rounded-xl border border-border px-4 py-3 text-left text-sm font-medium hover:bg-secondary" onClick={() => onNavigate("/admin/system")}>Review system health <ChevronRight className="size-4 text-muted-foreground" /></button></aside></section>
  </>;
}

function BusinessListRow({ business, onClick }: { business: PlatformBusiness; onClick: () => void }) {
  return <button data-control-layout="content" onClick={onClick} className="flex w-full flex-wrap items-center gap-3 px-5 py-4 text-left transition-colors hover:bg-secondary/45 sm:px-6"><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><Building2 className="size-[18px]" /></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{business.name}</span><span className="mt-1 block text-xs text-muted-foreground">{business._count.branches} branches · {business._count.memberships} team members</span></span><span className="hidden sm:inline"><StatusPill status={business.status} /></span><span className="hidden text-xs text-muted-foreground md:block">{business.plan?.name ?? "No plan"}</span><ChevronRight className="size-4 text-muted-foreground" /></button>;
}

function BusinessesSection({ query, value, onChange, onAction, canManage }: { query: { data?: PlatformBusiness[]; isPending: boolean; isError: boolean; error: unknown; refetch: () => unknown }; value: string; onChange: (value: string) => void; onAction: (action: ActionModel) => void; canManage: boolean }) {
  const rows = query.data ?? [];
  const columns: DataColumn<PlatformBusiness>[] = [
    { id: "name", header: "Business", accessorFn: (business) => business.name, cell: (business) => <div><Link href={`/admin/businesses/${business.id}`} className="font-semibold no-underline hover:underline">{business.name}</Link><p className="mt-1 text-xs text-muted-foreground">Joined {shortDate(business.createdAt)}</p></div> },
    { id: "plan", header: "Plan", accessorFn: (business) => business.plan?.name ?? "", cell: (business) => business.plan?.name ?? <span className="text-muted-foreground">Unassigned</span> },
    { id: "branches", header: "Branches", accessorFn: (business) => business._count.branches, cell: (business) => <span className="tabular-nums">{business._count.branches}</span> },
    { id: "team", header: "Team", accessorFn: (business) => business._count.memberships, cell: (business) => <span className="tabular-nums">{business._count.memberships}</span> },
    { id: "status", header: "Status", accessorFn: (business) => business.status, cell: (business) => <StatusPill status={business.status} /> },
  ];
  return <section className="overflow-hidden rounded-2xl border border-border/75 bg-card">
    <div className="flex flex-col gap-4 border-b border-border p-4 sm:flex-row sm:items-center sm:justify-between sm:p-5"><div><h3 className="font-semibold">Business directory</h3><p className="mt-1 text-xs text-muted-foreground">Search workspace names and open a business to review its account.</p></div><label className="relative block w-full sm:max-w-sm"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input value={value} onChange={(event) => onChange(event.target.value)} className="h-10 pl-9" placeholder="Search businesses…" aria-label="Search businesses" /></label></div>
    {query.isPending ? <LoadingRows /> : query.isError ? <StatePanel title="Businesses could not be loaded" description={getErrorMessage(query.error)} retry={() => void query.refetch()} /> : rows.length ? <><div className="p-3 sm:p-4"><DataTable rows={rows} columns={columns} getRowId={(business) => business.id} enableRowSelection={canManage ? (business) => business.status === "ACTIVE" : false} actions={canManage ? (business) => <><Button type="button" variant="ghost" size="sm" title={business.status === "ACTIVE" ? "Suspend business" : "Reactivate business"} onClick={() => onAction({ kind: business.status === "ACTIVE" ? "SUSPEND_BUSINESS" : "RESTORE_BUSINESS", subject: business.name, resourceId: business.id })}>{business.status === "ACTIVE" ? <XCircle className="size-4" /> : <Check className="size-4" />}</Button><Button type="button" variant="ghost" size="sm" title="Delete business" onClick={() => onAction({ kind: "DELETE_BUSINESS", subject: business.name, resourceId: business.id })}><Trash2 className="size-4 text-destructive" /></Button></> : undefined} bulkActions={({ selectedRows, clearSelection }) => <><Button type="button" size="sm" variant="outline" onClick={() => { onAction({ kind: "BULK_SUSPEND_BUSINESSES", subject: "selected businesses", resourceIds: selectedRows.map(({ id }) => id) }); clearSelection(); }}><XCircle className="size-4" />Suspend selected</Button><Button type="button" size="sm" variant="destructive" onClick={() => { onAction({ kind: "BULK_DELETE_BUSINESSES", subject: "selected businesses", resourceIds: selectedRows.map(({ id }) => id) }); clearSelection(); }}><Trash2 className="size-4" />Delete selected</Button></>} empty={<EmptyState icon={Building2} title={value ? "No businesses match that search" : "No businesses registered"} description={value ? "Try another name or clear your search." : "New businesses will appear here when they join Novara."} />} /></div><p className="border-t border-border px-5 py-3 text-xs text-muted-foreground">Showing up to 100 businesses. Use search to narrow the list.</p></> : <EmptyState icon={Building2} title={value ? "No businesses match that search" : "No businesses registered"} description={value ? "Try another name or clear your search." : "New businesses will appear here when they join Novara."} />}
  </section>;
}

function BusinessDetailSection({ query, plans, canManage, planPending, onPlanChange, onAction, onBack }: { query: { data?: BusinessDetails; isPending: boolean; isError: boolean; error: unknown; refetch: () => unknown }; plans: SubscriptionPlan[]; canManage: boolean; planPending: boolean; onPlanChange: (planId: string | null) => void; onAction: (action: ActionModel) => void; onBack: () => void }) {
  if (query.isPending) return <LoadingGrid />;
  if (query.isError || !query.data) return <StatePanel title="Business details are unavailable" description={getErrorMessage(query.error)} retry={() => void query.refetch()} />;
  const business = query.data;
  return <>
    <button className="mb-4 inline-flex items-center gap-2 text-sm font-medium text-muted-foreground hover:text-foreground" onClick={onBack}><ArrowDownRight className="size-4 rotate-45" />Back to businesses</button>
    <section className="rounded-2xl border border-border/75 bg-card p-5 sm:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div className="flex items-center gap-4"><span className="grid size-14 place-items-center rounded-2xl bg-secondary text-primary"><Building2 className="size-6" /></span><div><div className="flex flex-wrap items-center gap-3"><h3 className="text-2xl font-semibold">{business.name}</h3><StatusPill status={business.status} /></div><p className="mt-1.5 text-sm text-muted-foreground">Joined {shortDate(business.createdAt)} · {business.currency}</p></div></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => onAction({ kind: business.status === "ACTIVE" ? "SUSPEND_BUSINESS" : "RESTORE_BUSINESS", subject: business.name, resourceId: business.id })}>{business.status === "ACTIVE" ? "Suspend business" : "Reactivate"}</Button><Button variant="destructive" onClick={() => onAction({ kind: "DELETE_BUSINESS", subject: business.name, resourceId: business.id })}><Trash2 className="size-4" />Delete</Button></div></div>
      <div className="mt-7 grid gap-4 sm:grid-cols-3"><div className="rounded-xl bg-secondary/55 p-4"><p className="text-xs text-muted-foreground">Subscription plan</p>{canManage ? <SelectField aria-label="Assign subscription plan" value={business.planId ?? "none"} disabled={planPending} onValueChange={(value) => onPlanChange(value === "none" ? null : value)} options={[{ value: "none", label: "No plan assigned" }, ...plans.filter((plan) => plan.isActive).map((plan) => ({ value: plan.id, label: plan.name }))]} triggerClassName="mt-2 bg-card" /> : <p className="mt-2 text-sm font-semibold">{business.plan?.name ?? "No plan assigned"}</p>}</div><div className="rounded-xl bg-secondary/55 p-4"><p className="text-xs text-muted-foreground">Branches</p><p className="mt-2 text-sm font-semibold">{business._count.branches}</p></div><div className="rounded-xl bg-secondary/55 p-4"><p className="text-xs text-muted-foreground">Team members</p><p className="mt-2 text-sm font-semibold">{business._count.memberships}</p></div></div></section>
    <section className="mt-5 grid gap-5 xl:grid-cols-2"><article className="rounded-2xl border border-border bg-card"><div className="border-b border-border p-5"><p className="text-xs text-muted-foreground">Locations</p><h3 className="mt-1 text-lg font-semibold">Branches</h3></div>{business.branches.length ? <ul className="divide-y divide-border">{business.branches.map((branch) => <li key={branch.id} className="flex items-center justify-between gap-4 px-5 py-4"><div className="min-w-0"><p className="truncate text-sm font-medium">{branch.name}</p><p className="mt-1 text-xs text-muted-foreground">{branch.timezone}</p></div><span className="shrink-0 text-xs text-muted-foreground">{shortDate(branch.createdAt)}</span></li>)}</ul> : <EmptyState icon={Building2} title="No branches" description="This business has not created a branch." />}</article>
      <article className="rounded-2xl border border-border bg-card"><div className="border-b border-border p-5"><p className="text-xs text-muted-foreground">Access</p><h3 className="mt-1 text-lg font-semibold">Business team</h3></div>{business.memberships.length ? <ul className="divide-y divide-border">{business.memberships.map((membership) => <li key={membership.user.id} className="flex items-center gap-3 px-5 py-3.5"><span className="grid size-9 shrink-0 place-items-center rounded-full bg-secondary text-xs font-semibold text-primary">{initials(membership.user.name)}</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium">{membership.user.name}</span><span className="block truncate text-xs text-muted-foreground">{membership.user.email}</span></span><span className="rounded-full bg-secondary px-2.5 py-1 text-[10px] font-medium">{membership.role.toLowerCase().replaceAll("_", " ")}</span></li>)}</ul> : <EmptyState icon={Users} title="No team members" description="No users have been assigned to this business." />}</article></section>
  </>;
}

function PlansSection({ query, formOpen, setFormOpen, editing, name, setName, description, setDescription, price, setPrice, currency, setCurrency, trialDays, setTrialDays, branches, setBranches, staff, setStaff, pending, onEdit, onSave, onAction }: { query: { data?: SubscriptionPlan[]; isPending: boolean; isError: boolean; error: unknown; refetch: () => unknown }; formOpen: boolean; setFormOpen: (open: boolean) => void; editing: boolean; name: string; setName: (value: string) => void; description: string; setDescription: (value: string) => void; price: string; setPrice: (value: string) => void; currency: string; setCurrency: (value: string) => void; trialDays: string; setTrialDays: (value: string) => void; branches: string; setBranches: (value: string) => void; staff: string; setStaff: (value: string) => void; pending: boolean; onEdit: (plan: SubscriptionPlan) => void; onSave: () => void; onAction: (action: ActionModel) => void }) {
  return <>
    <div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm text-muted-foreground">Plans define pricing and usage limits.</p></div><Button onClick={() => setFormOpen(!formOpen)}>{formOpen ? <XCircle className="size-4" /> : <Plus className="size-4" />}{formOpen ? "Cancel" : "New plan"}</Button></div>
    {formOpen ? <form className="mb-5 rounded-2xl border border-border bg-card p-5 sm:p-6" onSubmit={(event) => { event.preventDefault(); onSave(); }}><div className="mb-5"><h3 className="font-semibold">{editing ? "Edit plan" : "Create a plan"}</h3><p className="mt-1 text-sm text-muted-foreground">Set pricing, trial length and service limits for business assignments.</p></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Field label="Plan name"><Input required minLength={2} maxLength={100} value={name} onChange={(event) => setName(event.target.value)} placeholder="Starter" /></Field><Field label="Monthly price"><Input required type="number" min="0" step="0.01" value={price} onChange={(event) => setPrice(event.target.value)} /></Field><Field label="Currency"><Input required minLength={3} maxLength={3} value={currency} onChange={(event) => setCurrency(event.target.value.toUpperCase())} /></Field><Field label="Trial days"><Input required type="number" min="0" max="365" value={trialDays} onChange={(event) => setTrialDays(event.target.value)} /></Field><Field label="Branch limit"><Input type="number" min="1" value={branches} onChange={(event) => setBranches(event.target.value)} placeholder="Unlimited" /></Field><Field label="Staff limit"><Input type="number" min="1" value={staff} onChange={(event) => setStaff(event.target.value)} placeholder="Unlimited" /></Field><div className="sm:col-span-2 xl:col-span-3"><Field label="Description"><Input maxLength={500} value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What is included in this plan?" /></Field></div></div><div className="mt-5 flex justify-end"><Button type="submit" disabled={pending}>{editing ? <Check className="size-4" /> : <Plus className="size-4" />}{pending ? "Saving…" : editing ? "Save changes" : "Create plan"}</Button></div></form> : null}
    {query.isPending ? <LoadingGrid /> : query.isError ? <StatePanel title="Plans could not be loaded" description={getErrorMessage(query.error)} retry={() => void query.refetch()} /> : query.data?.length ? <section className="grid gap-4 lg:grid-cols-2 2xl:grid-cols-3">{query.data.map((plan) => <article key={plan.id} className="rounded-2xl border border-border/75 bg-card p-5 sm:p-6"><div className="flex items-start justify-between gap-3"><span className="grid size-11 place-items-center rounded-xl bg-secondary text-primary"><Tag className="size-5" /></span><StatusPill status={plan.isActive ? "ACTIVE" : "SUSPENDED"} /></div><h3 className="mt-5 text-xl font-semibold">{plan.name}</h3><p className="mt-1 min-h-10 text-sm leading-5 text-muted-foreground">{plan.description || "A Novara subscription tier."}</p><p className="mt-5 text-3xl font-semibold tracking-tight">{money(plan.priceMonthly, plan.currency)}<span className="ml-1 text-sm font-normal text-muted-foreground">/ month</span></p><div className="mt-5 space-y-3 border-t border-border pt-4 text-sm"><HealthSummaryRow label="Trial" value={`${plan.trialDays} days`} /><HealthSummaryRow label="Branches" value={plan.maxBranches ? `Up to ${plan.maxBranches}` : "Unlimited"} /><HealthSummaryRow label="Staff" value={plan.maxStaff ? `Up to ${plan.maxStaff}` : "Unlimited"} /><HealthSummaryRow label="Businesses using plan" value={`${plan._count.tenants}`} /></div><div className="mt-5 flex flex-wrap justify-end gap-2"><Button variant="outline" onClick={() => onEdit(plan)}><Pencil className="size-4" />Edit</Button>{plan.isActive ? <Button variant="outline" onClick={() => onAction({ kind: "DEACTIVATE_PLAN", subject: plan.name, resourceId: plan.id })}>Deactivate plan</Button> : <Button variant="outline" onClick={() => onAction({ kind: "ACTIVATE_PLAN", subject: plan.name, resourceId: plan.id })}>Activate plan</Button>}{!plan.isActive && plan._count.tenants === 0 ? <Button variant="destructive" onClick={() => onAction({ kind: "DELETE_PLAN", subject: plan.name, resourceId: plan.id })}><Trash2 className="size-4" />Delete plan</Button> : null}</div></article>)}</section> : <EmptyState icon={Tag} title="Create the first subscription plan" description="Plans can be created now and assigned to businesses as billing enrollment is added." />}
  </>;
}

function SupportStaffSection({ query, email, onEmail, pending, onAdd, onAction }: { query: { data?: SupportAgent[]; isPending: boolean; isError: boolean; error: unknown; refetch: () => unknown }; email: string; onEmail: (value: string) => void; pending: boolean; onAdd: () => void; onAction: (action: ActionModel) => void }) {
  return <><section className="mb-5 rounded-2xl border border-border/75 bg-card p-5 sm:p-6"><div className="flex items-start gap-3"><span className="grid size-10 place-items-center rounded-xl bg-secondary text-primary"><UserPlus className="size-5" /></span><div><h3 className="font-semibold">Assign a Support Agent</h3><p className="mt-1 text-sm leading-6 text-muted-foreground">The person must already have an active Novara account. They will be able to search and view business account context.</p></div></div><form className="mt-5 flex flex-col gap-2 sm:flex-row" onSubmit={(event) => { event.preventDefault(); onAdd(); }}><Input type="email" required value={email} onChange={(event) => onEmail(event.target.value)} placeholder="support@novara.com" aria-label="Support agent email" /><Button disabled={pending}><UserPlus className="size-4" />{pending ? "Assigning…" : "Assign role"}</Button></form></section>
    <section className="overflow-hidden rounded-2xl border border-border/75 bg-card"><div className="border-b border-border p-5"><p className="text-xs text-muted-foreground">Platform access</p><h3 className="mt-1 text-lg font-semibold">Support Agents</h3></div>{query.isPending ? <LoadingRows /> : query.isError ? <StatePanel title="Support staff could not be loaded" description={getErrorMessage(query.error)} retry={() => void query.refetch()} /> : query.data?.length ? <div className="divide-y divide-border">{query.data.map((agent) => <div key={agent.id} className="flex flex-wrap items-center gap-3 p-4 sm:px-5"><span className="grid size-10 place-items-center rounded-full bg-secondary text-xs font-semibold text-primary">{initials(agent.user.name)}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{agent.user.name}</p><p className="truncate text-xs text-muted-foreground">{agent.user.email}</p></div><span className="rounded-full bg-secondary px-2.5 py-1 text-[10px] font-medium">Support Agent</span><Button variant="ghost" size="icon" aria-label={`Remove ${agent.user.name}`} onClick={() => onAction({ kind: "REMOVE_SUPPORT_AGENT", subject: agent.user.name, resourceId: agent.user.id })}><Trash2 className="size-4 text-destructive" /></Button></div>)}</div> : <EmptyState icon={LifeBuoy} title="No Support Agents assigned" description="Assign an existing Novara account when your support team is ready." />}</section></>;
}

function SupportWorkspaceSection() { return <div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><article className="rounded-2xl border border-border bg-card p-6 sm:p-8"><span className="grid size-12 place-items-center rounded-2xl bg-secondary text-primary"><LifeBuoy className="size-6" /></span><p className="mt-6 text-[10px] font-semibold uppercase tracking-[.18em] text-muted-foreground">Support workspace</p><h3 className="mt-2 text-2xl font-semibold">Help businesses get back to service.</h3><p className="mt-3 max-w-lg text-sm leading-6 text-muted-foreground">Search a business to review its status, branches, subscription plan and team access. Sensitive billing and platform controls stay restricted to Super Admins.</p><Link href="/admin/businesses" className="mt-6 inline-flex h-10 items-center gap-2 rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground no-underline hover:bg-primary/85">Find a business <ArrowRight className="size-4" /></Link></article><aside className="rounded-2xl border border-border bg-card p-6"><p className="text-xs text-muted-foreground">Your access</p><h3 className="mt-1 text-lg font-semibold">Support Agent</h3><div className="mt-5 space-y-3 text-sm"><div className="flex items-center gap-2"><Check className="size-4 text-emerald-600" />Search and view businesses</div><div className="flex items-center gap-2"><XCircle className="size-4 text-muted-foreground" />Change plans or system settings</div><div className="flex items-center gap-2"><XCircle className="size-4 text-muted-foreground" />Suspend or delete businesses</div></div></aside></div>; }

function PlatformTicketsSection({ query, pending, canResolveBusinessComplaints, onStatusChange }: { query: { data?: PlatformTicket[]; isPending: boolean; isError: boolean; error: unknown; refetch: () => unknown }; pending: boolean; canResolveBusinessComplaints: boolean; onStatusChange: (id: string, status: PlatformTicket["status"]) => void }) {
  return <section className="overflow-hidden rounded-2xl border border-border/75 bg-card">
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border p-5 sm:px-6"><div><h3 className="font-semibold">Customer inbox</h3><p className="mt-1 text-xs text-muted-foreground">Global visibility for Super Admins and Support Agents. Business complaints are resolved by their Owner or Manager.</p></div><span className="rounded-full bg-secondary px-3 py-1 text-xs">{query.data?.filter((ticket) => ticket.status === "OPEN" || ticket.status === "IN_PROGRESS").length ?? 0} active</span></div>
    {query.isPending ? <LoadingRows /> : query.isError ? <StatePanel title="Support tickets could not be loaded" description={getErrorMessage(query.error)} retry={() => void query.refetch()} /> : query.data?.length ? <div className="divide-y divide-border">{query.data.map((ticket) => <article key={ticket.id} className="grid gap-4 p-4 sm:grid-cols-[minmax(0,1fr)_190px] sm:items-start sm:px-6 sm:py-5"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-secondary px-2.5 py-1 text-[10px] font-semibold">{ticket.type}</span><span className={cn("rounded-full px-2.5 py-1 text-[10px] font-semibold", ticket.status === "OPEN" ? "bg-amber-500/10 text-amber-800 dark:text-amber-300" : ticket.status === "IN_PROGRESS" ? "bg-blue-500/10 text-blue-800 dark:text-blue-300" : "bg-emerald-500/10 text-emerald-800 dark:text-emerald-300")}>{ticket.status.replaceAll("_", " ")}</span><span className="text-[11px] text-muted-foreground">{ticket.priority} priority</span></div><h4 className="mt-2 text-sm font-semibold">{ticket.subject}</h4><p className="mt-1 max-w-4xl whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{ticket.message}</p><p className="mt-3 text-xs text-muted-foreground">{ticket.createdBy.name} · {ticket.createdBy.email}{ticket.tenant ? ` · ${ticket.tenant.name}` : ""} · {shortDate(ticket.createdAt)}</p></div>{ticket.type === "COMPLAINT" && ticket.tenantId && !canResolveBusinessComplaints ? <p className="text-xs leading-5 text-muted-foreground">A Super Admin or the business Owner/Manager can update this complaint.</p> : <div className="space-y-2"><label className="block text-xs font-medium text-muted-foreground" htmlFor={`platform-ticket-${ticket.id}`}>Update status</label><SelectField id={`platform-ticket-${ticket.id}`} value={ticket.status} disabled={pending} onValueChange={(value) => onStatusChange(ticket.id, value as PlatformTicket["status"])} options={[{ value: "OPEN", label: "Open" }, { value: "IN_PROGRESS", label: "In progress" }, { value: "RESOLVED", label: "Resolved" }, { value: "CLOSED", label: "Closed" }]} triggerClassName="h-10" /> </div>}</article>)}</div> : <EmptyState icon={MessageSquareText} title="Your inbox is clear" description="Customer complaints, feedback and support requests will show up here." />}
  </section>;
}

function SystemSection({ query }: { query: { data?: PlatformHealth; isPending: boolean; isError: boolean; error: unknown; refetch: () => unknown } }) {
  if (query.isPending) return <LoadingGrid />;
  if (query.isError || !query.data) return <StatePanel title="System health is unavailable" description={getErrorMessage(query.error)} retry={() => void query.refetch()} />;
  const health = query.data;
  return <><section className="rounded-2xl border border-border/75 bg-card p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div className="flex items-center gap-3"><span className="grid size-11 place-items-center rounded-xl bg-emerald-500/10 text-emerald-700 dark:text-emerald-300"><Activity className="size-5" /></span><div><p className="text-xs text-muted-foreground">Overall platform status</p><h3 className="mt-1 text-xl font-semibold">All systems {health.status}</h3></div></div><StatusPill status={health.status} /></div><p className="mt-5 text-xs text-muted-foreground">Last checked {new Intl.DateTimeFormat("en", { dateStyle: "medium", timeStyle: "short" }).format(new Date(health.checkedAt))} · Refreshes every minute</p></section>
    <section className="mt-5 grid gap-4 md:grid-cols-2">{health.services.map((service) => <article key={service.name} className="flex items-center gap-4 rounded-2xl border border-border/75 bg-card p-5"><span className="grid size-11 place-items-center rounded-xl bg-secondary text-primary">{service.name === "PostgreSQL" ? <Database className="size-5" /> : <Globe2 className="size-5" />}</span><div className="min-w-0 flex-1"><h4 className="font-semibold">{service.name}</h4><p className="mt-1 text-xs text-muted-foreground">Core platform dependency</p></div><StatusPill status={service.status} /></article>)}</section>
    <section className="mt-5 rounded-2xl border border-border/75 bg-card p-5 sm:p-6"><div className="mb-5 flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-secondary text-primary"><PackageCheck className="size-5" /></span><div><p className="text-xs text-muted-foreground">Runtime</p><h3 className="text-lg font-semibold">Service environment</h3></div></div><div className="grid gap-3 sm:grid-cols-3"><RuntimeValue label="Environment" value={health.runtime.environment} /><RuntimeValue label="Node.js" value={health.runtime.nodeVersion} /><RuntimeValue label="Process uptime" value={formatUptime(health.runtime.uptimeSeconds)} /></div></section></>;
}

function formatUptime(seconds: number) { const days = Math.floor(seconds / 86400); const hours = Math.floor((seconds % 86400) / 3600); const minutes = Math.floor((seconds % 3600) / 60); return days ? `${days}d ${hours}h` : hours ? `${hours}h ${minutes}m` : `${minutes}m`; }
function RuntimeValue({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-secondary/60 p-4"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-2 text-sm font-semibold capitalize">{value}</p></div>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="block space-y-1.5 text-xs font-medium text-muted-foreground">{label}{children}</label>; }
function HealthSummaryRow({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between gap-4 border-b border-border/70 pb-3 text-sm last:border-0 last:pb-0"><span className="text-muted-foreground">{label}</span><span className="text-right font-semibold">{value}</span></div>; }
function EmptyState({ icon: Icon, title, description }: { icon: typeof Building2; title: string; description: string }) { return <div className="flex min-h-52 flex-col items-center justify-center px-5 py-10 text-center"><span className="grid size-12 place-items-center rounded-2xl bg-secondary text-primary"><Icon className="size-5" /></span><h3 className="mt-4 font-semibold">{title}</h3><p className="mt-1.5 max-w-md text-sm leading-6 text-muted-foreground">{description}</p></div>; }
function LoadingGrid() { return <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4" aria-busy="true">{Array.from({ length: 4 }, (_, index) => <div key={index} className="h-36 animate-pulse rounded-2xl bg-secondary/70" />)}<span className="sr-only">Loading platform data…</span></div>; }
function LoadingRows() { return <div className="space-y-3 p-5" aria-busy="true">{Array.from({ length: 5 }, (_, index) => <div key={index} className="h-14 animate-pulse rounded-xl bg-secondary/60" />)}<span className="sr-only">Loading records…</span></div>; }
